// Interface-only state. Repository paths and revisions are illustrative; no Git or filesystem access.
const scInitialFiles = [
  {id:'review',path:'harnesses/claude-code/global/skills/code-review/SKILL.md',kind:'Skill',head:'# Code review\n\nReview correctness and tests.\nReport all findings.',working:'# Code review\n\nReview correctness and tests.\nPrioritize actionable findings.\nCheck security boundaries.',index:undefined},
  {id:'mcp',path:'harnesses/claude-code/global/mcp/context7.json',kind:'MCP',head:'{\n  "command": "npx",\n  "timeout": 20\n}',working:'{\n  "command": "npx",\n  "timeout": 30\n}',index:undefined},
  {id:'old',path:'harnesses/codex/global/skills/legacy-review/SKILL.md',kind:'Skill',head:'# Legacy review\nUse the old checklist.',working:null,index:undefined},
  {id:'new',path:'shared/skills/test-first/SKILL.md',kind:'Skill',head:null,working:'# Test first\n\nWrite a failing test before the fix.',index:'# Test first\n\nWrite a failing test before the fix.'}
];
let scFiles=scInitialFiles.map(x=>({...x}));
let scGitTab='changes';
let scArea='git',scSelected={id:'review',area:'working'},scMessage='',scNotice='';
let scRemote={ahead:1,behind:0,offline:false,fetched:'10:42',diverged:false};
let scHistory=[{hash:'4b2e09c',message:'更新工程开发配置组合',state:'待推送',files:[]},{hash:'8c4f2a1',message:'新增 code-review 与 context7',state:'已提交',files:[]}];
let scIncoming=[],scExample='ahead';
const scBaseReview='# Code review\nReview correctness and tests.\nReport all findings.';
const scBaseMcp='{\n  "command": "npx",\n  "timeout": 20\n}';
const scNewReview='# Code review\nReview correctness and tests.\nPrioritize actionable findings.\nCheck security boundaries.';
const scHarnessSeed={
  'Claude Code':{review:scNewReview,mcp:'{\n  "command": "npx",\n  "timeout": 30\n}',agent:'# Project instructions\nUse Corepack.\nVerify architecture boundaries.',notes:'# Personal notes\nUse focused tests.',hook:'Run pre-commit before commit.'},
  'Codex':{review:scBaseReview,mcp:'{\n  "command": "npx",\n  "timeout": 20,\n  "enabled": true\n}',agent:'# Project instructions\nUse Corepack.\nRun integration tests.',notes:null,hook:null},
  'Cursor':{review:'# Code review\nReview correctness and tests.\nUse the Cursor checklist.',mcp:scBaseMcp,agent:'# Project instructions\nUse Corepack.',notes:null,hook:null},
  'OpenCode':{review:scNewReview,mcp:scBaseMcp,agent:'# Project instructions\nUse Corepack.',notes:null,hook:null}
};
let scHarnessData=Object.fromEntries(['全局','RuleSwitch','RHIZA'].map(scope=>[scope,structuredClone(scHarnessSeed)]));
let scSource='Claude Code',scTargets=['Codex'],scScope='全局',scPairKey='Codex:review';
let scChosen=new Set(['Codex:review','Codex:notes']),scModes={},scPairPlan=[];
function scIndex(file){return file.index===undefined?file.head:file.index}
function scWorkingFiles(){return scFiles.filter(f=>f.conflict||f.working!==scIndex(f))}
function scStagedFiles(){return scFiles.filter(f=>f.index!==undefined&&f.index!==f.head)}
function scChangeCount(){return scFiles.filter(f=>f.conflict||f.working!==f.head||f.index!==undefined).length}
function scStatus(before,after,conflict=false){return conflict?'U':before===null?'A':after===null?'D':'M'}
function scEnsureSelection(){const lists={working:scWorkingFiles(),staged:scStagedFiles()};if(!lists[scSelected.area]?.some(f=>f.id===scSelected.id)){const f=lists.working[0]||lists.staged[0];scSelected={id:f?.id||'',area:lists.working.length?'working':'staged'}}}
function scRefresh(){scEnsureSelection();render()}
function scStage(id){const f=scFiles.find(x=>x.id===id);if(!f||f.conflict)return false;f.index=f.working;return true}
function scUnstage(id){const f=scFiles.find(x=>x.id===id);if(f)f.index=undefined}
function scCommit(message){if(!message.trim())return '请填写提交说明';if(scFiles.some(f=>f.conflict))return '先解决合并冲突';const staged=scStagedFiles();if(!staged.length)return '请先暂存要提交的文件';const snapshots=staged.map(f=>({path:f.path,before:f.head,after:f.index}));staged.forEach(f=>{f.head=f.index;f.index=undefined});scRemote.ahead++;scHistory.unshift({hash:'demo'+(scHistory.length+1),message:message.trim(),state:'待推送',files:snapshots});scMessage='';scNotice='已提交到本地 Git（示例）；推送后远端才会更新。';return ''}
function scPushBlock(){if(scRemote.offline)return '远端不可用，稍后重新 Fetch';if(scFiles.some(f=>f.conflict))return '存在合并冲突';if(scRemote.behind)return scRemote.ahead?'本地与远端已分叉，先检查提交差异':'先拉取远端更新';if(!scRemote.ahead)return '没有待推送提交';return ''}
function scPullBlock(){if(scRemote.offline)return '远端不可用';if(scRemote.ahead&&scRemote.behind)return '分支已分叉，不能快进拉取';if(scFiles.some(f=>f.conflict))return '先完成当前冲突处理';if(scChangeCount())return '先提交或撤销工作区修改，再拉取';if(!scRemote.behind)return '没有待拉取提交';return ''}
function scGitAction(action){if(action==='fetch'){if(scRemote.offline){scNotice='Fetch 失败：远端连接不可用；工作区和本地提交均保留。'}else{scRemote.fetched='刚刚';scNotice='已更新远端引用（示例）；工作区内容与本地提交未改变。'}scRefresh();return}const reason=action==='push'?scPushBlock():scPullBlock();if(reason){scNotice=reason;scRefresh();return}modal(action==='push'?'推送到 origin/main':'拉取 origin/main',action==='push'?'本地提交 → 远端仓库':'远端提交 → 本地分支',`<p>${action==='push'?scRemote.ahead+' 个本地提交将上传；未提交文件不在本次推送中。':scRemote.behind+' 个远端提交将以快进方式更新本地仓库。'}</p><p class="subtitle">${action==='push'?'各 Harness 的运行时配置不会因此自动更新。':'拉取后可以在 Harness 配置中检查集合间的差异；工具运行时应用需另行确认。'}</p>`,btn('演示'+(action==='push'?'推送':'拉取'),'sc-'+action+'-confirm','primary'))}
function scConfirmRemote(action){if((action==='push'?scPushBlock():scPullBlock()))return;if(action==='push'){scHistory.forEach(x=>{if(x.state==='待推送')x.state='已推送'});scRemote.ahead=0}else{scHistory.unshift(...scIncoming.map(x=>({...x,state:'已拉取'})));scIncoming=[];scRemote.behind=0}scRemote.fetched='刚刚';scNotice=action==='push'?'推送完成（示例）；仅上传已提交的 Git 版本。':'快进拉取完成（示例）；尚未应用到本机工具。';$('#dialog').close();scRefresh()}
function scScenario(value){scExample=value;scFiles=scInitialFiles.map(x=>({...x}));scRemote={ahead:1,behind:0,offline:false,fetched:'10:42',diverged:false};scHistory=[{hash:'4b2e09c',message:'更新工程开发配置组合',state:'待推送',files:[]},{hash:'8c4f2a1',message:'新增 code-review 与 context7',state:'已提交',files:[]}];scIncoming=[];scNotice='';scMessage='';if(value==='behind'){scFiles=[];scRemote.ahead=0;scRemote.behind=2;scHistory=scHistory.slice(1)}if(value==='diverged'){scRemote.behind=2;scRemote.diverged=true}if(value==='offline')scRemote.offline=true;if(value==='conflict'){scFiles[0].conflict=true;scFiles[0].incoming='# Code review\nReview correctness and tests.\nCheck compatibility.';scRemote.ahead=0;scHistory[0].state='已提交';scNotice='示例合并尚未完成：解决冲突并暂存结果后再提交。'}if(value==='clean'){scFiles=[];scRemote.ahead=0;scHistory=scHistory.slice(1)}if(scRemote.behind)scIncoming=[{hash:'a9d3c72',message:'更新仓库中的 MCP 超时配置',state:'待拉取',files:[]},{hash:'02ea854',message:'调整共享指令文件',state:'待拉取',files:[]}];scRefresh()}
function scFileList(area){const files=area==='working'?scWorkingFiles():scStagedFiles();return `<section class="sc-file-group"><div class="sc-list-title"><h3>${area==='working'?'更改':'暂存的更改'} <span>${files.length}</span></h3><button class="quiet" data-action="sc-${area==='working'?'stage':'unstage'}-all" ${!files.length?'disabled':''} aria-label="${area==='working'?'暂存所有更改':'取消全部暂存'}">${area==='working'?'＋':'−'}</button></div>${files.map(f=>{const before=area==='working'?scIndex(f):f.head,after=area==='working'?f.working:f.index,status=scStatus(before,after,f.conflict);const parts=f.path.split('/');return `<div class="sc-file ${scSelected.id===f.id&&scSelected.area===area?'active':''}"><button class="sc-file-select" data-sc-file="${f.id}" data-sc-area="${area}" aria-pressed="${scSelected.id===f.id&&scSelected.area===area}"><span class="sc-status ${status==='D'||status==='U'?'warning':'status'}">${status}</span><span><strong>${escapeHtml(parts.at(-1))}</strong><small>${escapeHtml(parts.slice(0,-1).join('/'))}</small></span></button><div class="sc-file-actions">${area==='working'?`<button data-sc-stage="${f.id}" aria-label="暂存 ${escapeHtml(f.path)}" ${f.conflict?'disabled':''}>＋</button><button data-sc-discard="${f.id}" aria-label="撤销 ${escapeHtml(f.path)}">↶</button>`:`<button data-sc-unstage="${f.id}" aria-label="取消暂存 ${escapeHtml(f.path)}">−</button>`}</div></div>`}).join('')||'<p class="sc-empty-list">没有'+(area==='working'?'未暂存':'已暂存')+'的更改</p>'}</section>`}
function scDiff(left,right,leftTitle,rightTitle){const l=(left??'').split('\n'),r=(right??'').split('\n');const code=(lines,other,side,missing)=>missing?'<div class="sc-no-file">该版本中不存在此文件</div>':lines.map((line,i)=>`<div class="sc-code-line ${!other.includes(line)?side:''}"><span>${i+1}</span><code>${escapeHtml(line)||' '}</code></div>`).join('');return `<div class="sc-diff-grid"><section><div class="sc-diff-label">${escapeHtml(leftTitle)}</div><div class="sc-code">${code(l,r,'sc-removed',left===null)}</div></section><section><div class="sc-diff-label">${escapeHtml(rightTitle)}</div><div class="sc-code">${code(r,l,'sc-added',right===null)}</div></section></div>`}
function scSelectedDiff(){const f=scFiles.find(x=>x.id===scSelected.id);if(!f)return `<div class="sc-diff-empty"><h3>工作区已整理</h3><p>选择提交查看历史，或 Fetch 检查远端更新。</p></div>`;const staged=scSelected.area==='staged';return `<div class="sc-editor-title"><div><strong>${escapeHtml(f.path.split('/').at(-1))}</strong><small>${escapeHtml(f.path)}</small></div><span>${f.conflict?tag('合并冲突'):tag(staged?'已暂存':'未暂存')}</span></div>${f.conflict?`<div class="sc-inline-warning">当前工作区存在合并冲突。${btn('处理合并冲突','sc-resolve','small')}</div>`:''}${scDiff(staged?f.head:scIndex(f),staged?f.index:f.working,staged?'HEAD · 上次提交':'Index · 暂存版本',staged?'Index · 下次提交内容':'Working Tree · 工作区')}<div class="sc-editor-foot">${staged?'提交只包含暂存版本。':'此处比较工作区与暂存版本；暂存后再检查提交内容。'}</div>`}
function scHistoryList(){return `<div class="sc-history-title"><h3>提交记录</h3><span class="muted">⑂ main → origin/main</span></div><div class="sc-history">${[...scIncoming,...scHistory].map((c,i)=>`<button class="sc-commit-row" data-sc-commit="${i}"><span class="sc-graph ${c.state==='待拉取'?'warning':''}">●</span><span>${escapeHtml(c.message)}<small>${escapeHtml(c.hash)} · Dongxin · 示例提交</small></span>${tag((c===scHistory[0]?'main · ':'')+(c===scHistory[scRemote.ahead]&&!scRemote.behind?'origin/main · ':'')+c.state)}</button>`).join('')}</div>`}
function scGitView(){return `<div class="sc-repo-bar"><div><strong>agent-environment</strong><span class="muted">⑂ main &nbsp; → &nbsp; origin/main</span></div><div class="sc-remote-count"><span>↑ ${scRemote.ahead} 待推送</span><span>↓ ${scRemote.behind} 待拉取</span><small>${scRemote.offline?'远端不可用':'Fetch '+scRemote.fetched}</small></div></div><div class="sc-git-actions"><span class="muted">工作区 → 暂存 → 本地提交 → 远端</span><div class="actions">${btn('Fetch','sc-fetch','small')}<button data-action="sc-pull" class="small" title="${scPullBlock()||'快进拉取远端提交'}" ${scPullBlock()?'disabled':''}>↓ 拉取</button><button data-action="sc-push" class="small" title="${scPushBlock()||'推送本地提交'}" ${scPushBlock()?'disabled':''}>↑ 推送</button>${btn('分支 / 远程','sc-repository','quiet small')}</div></div>${scRemote.behind&&scRemote.ahead?'<div class="sc-inline-warning">main 与 origin/main 已分叉。当前策略为快进同步；先比较双方提交，明确处理后再继续。'+btn('比较分叉提交','sc-divergence','small')+'</div>':''}${scRemote.offline?'<div class="sc-inline-warning">远端连接失败，本地更改和提交仍可管理。重新 Fetch 后再确认远端状态。</div>':''}${scNotice?`<p class="sc-notice ${scRemote.offline?'warning':''}" role="status">${escapeHtml(scNotice)}</p>`:''}<div class="tabs sc-git-tabs" aria-label="Git 工作区视图"><button data-sc-git-tab="changes" class="${scGitTab==='changes'?'active':''}" aria-pressed="${scGitTab==='changes'}">文件更改 ${tag(scChangeCount())}</button><button data-sc-git-tab="history" class="${scGitTab==='history'?'active':''}" aria-pressed="${scGitTab==='history'}">提交记录 ${tag(scIncoming.length+scHistory.length)}</button></div>${scGitTab==='history'?`<section class="sc-history-panel" aria-label="提交记录">${scHistoryList()}</section>`:`<div class="sc-git-layout"><aside class="sc-changes-panel"><div class="sc-commit-box"><label for="sc-commit-message">提交说明</label><textarea id="sc-commit-message" placeholder="说明这次配置修改…" rows="2">${escapeHtml(scMessage)}</textarea><button class="primary" data-action="sc-commit" id="sc-commit-button" ${!scMessage.trim()||!scStagedFiles().length||scFiles.some(f=>f.conflict)?'disabled':''}>✓ 提交 ${scStagedFiles().length?tag(scStagedFiles().length):''}</button><small>提交到本地 Git；推送单独执行。</small></div>${scFileList('staged')}${scFileList('working')}</aside><section class="sc-review-panel">${scSelectedDiff()}</section></div>`}<details class="sc-demo-controls"><summary>原型示例状态</summary><select id="sc-scenario" aria-label="Git 示例状态"><option value="ahead" ${scExample==='ahead'?'selected':''}>有本地更改与待推送提交</option><option value="behind" ${scExample==='behind'?'selected':''}>工作区干净 · 远端领先</option><option value="diverged" ${scExample==='diverged'?'selected':''}>本地与远端分叉</option><option value="offline" ${scExample==='offline'?'selected':''}>远端不可用</option><option value="conflict" ${scExample==='conflict'?'selected':''}>合并冲突</option><option value="clean" ${scExample==='clean'?'selected':''}>全部同步</option></select><span>切换会重置当前 Git 演示数据。</span></details>`}
function scAssetDefs(){return scScope==='全局'?[{id:'review',name:'code-review',kind:'Skills',path:'skills/code-review/SKILL.md',base:scBaseReview},{id:'mcp',name:'context7',kind:'MCP',path:'mcp/context7.json',base:scBaseMcp},{id:'notes',name:'personal-notes',kind:'Skills',path:'skills/personal-notes/SKILL.md',base:null}]:[{id:'agent',name:'项目指令',kind:'Instructions',path:'instructions/AGENTS.md',base:'# Project instructions\nUse Corepack.'},{id:'mcp',name:'context7',kind:'MCP',path:'mcp/context7.json',base:scBaseMcp},{id:'hook',name:'pre-commit',kind:'Hooks',path:'hooks/pre-commit.json',base:null}]}
function scHarnessPath(tool,def){const slug=tool.toLowerCase().replace(/[^a-z0-9]+/g,'-');return `harnesses/${slug}/${scScope==='全局'?'global':'projects/'+scScope}/${def.path}`}
function scCompareState(source,target,base){if(source===target)return '相同';if(source===null)return '仅目标存在';if(target===null)return '仅来源存在';if(source!==base&&target!==base)return '双方有修改';return source!==base?'来源有更新':'目标有修改'}
function scPairRows(){return scTargets.flatMap(target=>scAssetDefs().map(def=>{const source=scHarnessData[scScope][scSource]?.[def.id]??null,value=scHarnessData[scScope][target]?.[def.id]??null;const supported=!manualHarnesses.some(x=>x.name===target||x.name===scSource)&&(def.kind!=='Hooks'||target==='Claude Code');const state=supported?scCompareState(source,value,def.base):'暂不支持';const key=target+':'+def.id;const mode=scModes[key]||(state==='相同'||state==='仅目标存在'?'keep':state==='双方有修改'||state==='目标有修改'?'unresolved':source===null?'keep':'replace');return {...def,key,target,source,value,state,mode,supported}}))}
function scMergeValues(row){if(row.kind!=='MCP')return {error:'此类型需要手动编辑合并结果'};try{const base=JSON.parse(row.base||'{}'),src=JSON.parse(row.source||'{}'),dst=JSON.parse(row.value||'{}'),out={...dst};for(const key of new Set([...Object.keys(base),...Object.keys(src)])){const changed=JSON.stringify(src[key])!==JSON.stringify(base[key]);if(!changed)continue;if(JSON.stringify(dst[key])!==JSON.stringify(base[key])&&JSON.stringify(dst[key])!==JSON.stringify(src[key]))return {error:'同名字段 '+key+' 双方均有修改'};if(src[key]===undefined)delete out[key];else out[key]=src[key]}return {value:JSON.stringify(out,null,2)}}catch{return {error:'配置格式无法解析'}}}
function scPlannedRows(){return scPairRows().filter(r=>scChosen.has(r.key)).map(r=>{let error='',result=r.source,action=r.value===null?'新增':'修改';if(!r.supported)error='此工具的配置映射尚不可用';if(r.mode==='unresolved')error='选择保留、覆盖或合并';if(r.mode==='keep'){action='跳过';result=r.value}if(r.mode==='merge'){const merge=scMergeValues(r);error=merge.error||error;result=merge.value}if(r.mode==='delete'){if(r.source!==null)error='来源仍有配置，不能作为移除依据';result=null;action='删除'}if(r.mode==='replace'&&r.source===null)error='来源不存在，选择保留或明确删除';return {...r,result,action,error}})}
function scPairDiff(){const r=scPairRows().find(x=>x.key===scPairKey)||scPairRows()[0];if(!r)return '<div class="sc-diff-empty"><h3>选择来源与目标工具</h3><p>比较仓库内的配置集合。</p></div>';return `<div class="sc-editor-title"><div><strong>${escapeHtml(r.name)}</strong><small>${escapeHtml(typeLabels[r.kind])} · ${escapeHtml(scScope)}</small></div>${tag(r.state)}</div>${scDiff(r.source,r.value,scSource+' · 来源仓库文件',r.target+' · 目标仓库文件')}<div class="sc-editor-foot"><span>${escapeHtml(scHarnessPath(scSource,r))}</span><span>${escapeHtml(scHarnessPath(r.target,r))}</span></div>`}
function scHarnessView(){const rows=scPairRows();return `<div class="sc-pair-controls"><label>来源<select id="sc-source">${harnessNames.map(n=>`<option ${n===scSource?'selected':''}>${escapeHtml(n)}</option>`).join('')}</select></label><span class="sc-direction">→</span><div class="sc-targets"><div class="sc-target-title"><strong>目标 Harness</strong><div class="actions">${btn('全选','sc-target-all','quiet small')}${btn('反选','sc-target-invert','quiet small')}</div></div><div class="sc-target-options">${harnessNames.filter(n=>n!==scSource).map(n=>`<label><input type="checkbox" data-sc-target="${escapeHtml(n)}" ${scTargets.includes(n)?'checked':''}>${escapeHtml(n)}</label>`).join('')}</div></div><label>范围<select id="sc-scope">${['全局','RuleSwitch','RHIZA'].map(n=>`<option ${n===scScope?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="sc-harness-hint"><span>仓库内同步：比较相同配置的内容与映射。同步后产生目标文件的未暂存更改。</span>${btn('读取工具本地修改…','sc-capture','quiet small')}</div><div class="sc-pair-layout"><div class="sc-pair-list"><div class="sc-list-title"><h3>配置差异 <span>${rows.filter(r=>r.state!=='相同').length}</span></h3><button class="quiet" data-action="sc-pair-select">选择可同步项</button></div>${rows.map(r=>`<div class="sc-pair-row ${scPairKey===r.key?'active':''}"><input type="checkbox" data-sc-pair="${escapeHtml(r.key)}" aria-label="选择 ${escapeHtml(r.target+' / '+r.name)}" ${scChosen.has(r.key)?'checked':''} ${r.state==='相同'||!r.supported?'disabled':''}><button data-sc-pair-view="${escapeHtml(r.key)}"><strong>${escapeHtml(r.name)}</strong><small>${escapeHtml(r.target)} · ${escapeHtml(typeLabels[r.kind])}</small><span class="${r.state==='相同'?'status':r.state==='双方有修改'||!r.supported?'warning':'muted'}">${r.state}</span></button><select data-sc-mode="${escapeHtml(r.key)}" aria-label="${escapeHtml(r.target+' / '+r.name)} 同步方式" ${r.state==='相同'||!r.supported?'disabled':''}>${[['unresolved','待处理'],['replace',r.value===null?'新增':'覆盖'],['keep','保留目标'],...(r.kind==='MCP'?[['merge','合并字段']]:[]),...(r.source===null?[['delete','删除目标']]:[])].map(([v,n])=>`<option value="${v}" ${r.mode===v?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')||'<div class="sc-diff-empty"><h3>尚未选择目标</h3><p>至少选择一个其他 Harness。</p></div>'}<div class="sc-pair-summary"><span>已选 ${scPlannedRows().length} 项</span><button data-action="sc-pair-plan" class="primary" ${!scPlannedRows().some(r=>r.action!=='跳过')?'disabled':''}>预览同步</button></div></div><section class="sc-review-panel">${scPairDiff()}<div class="sc-relation-note"><strong>统一由 Git 记录版本</strong><p>来源集合 → 目标集合 → 工作区更改 → 暂存 / 提交 → 推送远端。</p><small>两边的新增、修改与删除逐项确认；配置转换损失和目标独有内容单独处理。</small></div></section></div>`}
function sourceControlView(){return head('同步变更','Git 管理仓库版本，Harness 配置管理仓库内各工具的差异。')+`<div class="tabs sc-area-tabs"><button data-sc-area-tab="git" class="${scArea==='git'?'active':''}" ${scArea==='git'?'aria-current="page"':''}>⑂ Git 仓库</button><button data-sc-area-tab="harness" class="${scArea==='harness'?'active':''}" ${scArea==='harness'?'aria-current="page"':''}>⇄ Harness 配置</button><span>agent-environment · 当前本地仓库</span></div>${scArea==='git'?scGitView():scHarnessView()}`}
function scPairPreview(){scPairPlan=scPlannedRows();if(!scPairPlan.some(r=>r.action!=='跳过'))return;const blocked=scPairPlan.some(r=>r.error);modal('仓库内同步 · 预览',scSource+' → '+scTargets.join('、')+' · '+scScope,`<div class="sc-plan-table"><table class="table"><thead><tr><th>目标 / 配置</th><th>操作</th><th>说明</th></tr></thead><tbody>${scPairPlan.map(r=>`<tr><td>${escapeHtml(r.target+' / '+r.name)}<small>${escapeHtml(scHarnessPath(r.target,r))}</small></td><td>${r.error?'阻止':r.action}</td><td>${escapeHtml(r.error|| (r.action==='跳过'?'保留目标现有内容':r.mode==='merge'?'合并不同字段，保留目标独有字段':r.action==='新增'?'添加目标缺少的配置':'更新目标仓库文件，原内容可在差异中检查'))}</td></tr>`).join('')}</tbody></table></div>${scPairPlan.some(r=>r.action==='修改'&&r.mode==='replace'&&!r.error)?'<label class="overwrite-ack"><input type="checkbox" id="sc-pair-overwrite"> 确认更新以上目标配置；目标独有内容可能被替换。</label>':''}${scPairPlan.some(r=>r.action==='删除')?'<label class="overwrite-ack"><input type="checkbox" id="sc-pair-delete"> 确认删除所选目标仓库配置；工具运行时副本保留。</label>':''}<p class="subtitle">确认后更新仓库工作区，不自动提交或推送。原型只改变页面内存，不写入真实仓库。</p>`, `<button id="sc-pair-confirm" data-action="sc-pair-apply" class="primary" ${blocked?'disabled':''}>演示更新工作区</button>`);scUpdatePairConfirm()}
function scUpdatePairConfirm(){const ack=$('#sc-pair-overwrite'),del=$('#sc-pair-delete');$('#sc-pair-confirm').disabled=scPairPlan.some(r=>r.error)||!!(ack&&!ack.checked)||!!(del&&!del.checked)}
function scApplyPair(){if($('#sc-pair-confirm').disabled)return;for(const r of scPairPlan){if(r.action==='跳过')continue;scHarnessData[scScope][r.target]??={};scHarnessData[scScope][r.target][r.id]=r.result;const path=scHarnessPath(r.target,r),existing=scFiles.find(x=>x.path===path);if(existing)existing.working=r.result;else scFiles.push({id:'pair-'+scFiles.length,path,head:r.value,working:r.result,index:undefined,kind:r.kind})}$('#dialog').close();scChosen.clear();scNotice='Harness 配置已更新仓库工作区（示例）。请检查更改、暂存并提交；远端尚未更新。';scArea='git';scGitTab='changes';scRefresh()}
function scHandleClick(b){if(b.dataset.scGitTab){scGitTab=b.dataset.scGitTab;scRefresh();return true}if(b.dataset.scAreaTab){scArea=b.dataset.scAreaTab;scRefresh();return true}if(b.dataset.scFile){scSelected={id:b.dataset.scFile,area:b.dataset.scArea};scRefresh();return true}if(b.dataset.scStage){scStage(b.dataset.scStage);scRefresh();return true}if(b.dataset.scUnstage){scUnstage(b.dataset.scUnstage);scRefresh();return true}if(b.dataset.scDiscard){const f=scFiles.find(x=>x.id===b.dataset.scDiscard);modal('撤销工作区更改',f.path,`<p>将工作区恢复为${f.index===undefined?'HEAD':'暂存版本'}。${f.head===null?'新建文件将从工作区移除。':'未暂存的修改会丢失。'}</p>`,`<button class="primary" data-sc-discard-confirm="${f.id}">演示撤销</button>`);return true}if(b.dataset.scDiscardConfirm){const f=scFiles.find(x=>x.id===b.dataset.scDiscardConfirm);f.working=scIndex(f);f.conflict=false;$('#dialog').close();scRefresh();return true}if(b.dataset.scPairView){scPairKey=b.dataset.scPairView;scRefresh();return true}if(b.dataset.scCommit!==undefined){const c=[...scIncoming,...scHistory][Number(b.dataset.scCommit)];modal(c.message,c.hash+' · '+c.state,c.files.length?c.files.map(f=>`<h3>${escapeHtml(f.path)}</h3>${scDiff(f.before,f.after,'父提交','此提交')}`).join(''):'<p>此示例展示提交关系；选择工作区文件可查看完整差异。</p>');return true}return false}
function scHandleChange(e){const t=e.target;if(t.id==='sc-scenario'){scScenario(t.value);return true}if(t.id==='sc-source'){scSource=t.value;scTargets=scTargets.filter(n=>n!==scSource);scChosen.clear();scModes={};scRefresh();return true}if(t.id==='sc-scope'){scScope=t.value;scChosen.clear();scModes={};scRefresh();return true}if(t.dataset.scTarget){scTargets=t.checked?[...scTargets,t.dataset.scTarget]:scTargets.filter(n=>n!==t.dataset.scTarget);scChosen.clear();scModes={};scRefresh();return true}if(t.dataset.scPair){t.checked?scChosen.add(t.dataset.scPair):scChosen.delete(t.dataset.scPair);scRefresh();return true}if(t.dataset.scMode){scModes[t.dataset.scMode]=t.value;scRefresh();return true}if(t.id==='sc-pair-overwrite'||t.id==='sc-pair-delete'){scUpdatePairConfirm();return true}return false}
const scHandlers={
  'sc-fetch':()=>scGitAction('fetch'),'sc-push':()=>scGitAction('push'),'sc-pull':()=>scGitAction('pull'),'sc-push-confirm':()=>scConfirmRemote('push'),'sc-pull-confirm':()=>scConfirmRemote('pull'),
  'sc-stage-all':()=>{scWorkingFiles().forEach(f=>scStage(f.id));scRefresh()},'sc-unstage-all':()=>{scStagedFiles().forEach(f=>scUnstage(f.id));scRefresh()},
  'sc-commit':()=>{const error=scCommit(scMessage);if(error)toast(error);scRefresh()},
  'sc-repository':()=>modal('分支与远程','agent-environment',`<div class="detail-line"><span>当前本地分支</span><strong>main</strong></div><div class="detail-line"><span>跟踪分支</span><strong>origin/main</strong></div><div class="detail-line"><span>远程</span><strong>github.com/dongxin/agent-environment</strong></div><p class="subtitle">当前原型使用 main 分支；分支切换与创建在后续 Git 接入中实现。</p>`),
  'sc-divergence':()=>modal('比较分叉提交','main ↔ origin/main',scHistoryList()+'<p class="subtitle">快进策略无法直接整合分叉提交。实际接入时进入明确的 Merge / Rebase 处理，不自动改写历史。</p>'),
  'sc-resolve':()=>{const f=scFiles.find(x=>x.id===scSelected.id);modal('处理合并冲突',f.path,scDiff(f.working,f.incoming,'本地版本','传入版本')+'<p class="subtitle">选择结果后写入工作区并暂存，提交完成冲突处理。</p>',btn('保留本地版本','sc-resolve-local')+btn('使用传入版本','sc-resolve-incoming','primary'))},
  'sc-resolve-local':()=>scResolveConflict(false),'sc-resolve-incoming':()=>scResolveConflict(true),
  'sc-target-all':()=>{scTargets=harnessNames.filter(n=>n!==scSource);scChosen.clear();scModes={};scRefresh()},'sc-target-invert':()=>{scTargets=harnessNames.filter(n=>n!==scSource&&!scTargets.includes(n));scChosen.clear();scModes={};scRefresh()},
  'sc-pair-select':()=>{scChosen=new Set(scPairRows().filter(r=>r.supported&&!['相同','仅目标存在','双方有修改','目标有修改'].includes(r.state)).map(r=>r.key));scRefresh()},
  'sc-pair-plan':scPairPreview,'sc-pair-apply':scApplyPair,
  'sc-capture':()=>modal('读取工具本地修改',scSource+' · '+scScope+' → 仓库中的来源集合',`<p>将此工具在本机的修改读取到仓库中的对应 Harness 配置文件，再检查集合间的差异。</p><p class="subtitle">实际接入需检查配置映射与版本。当前原型使用固定数据，不扫描本机文件。</p>`,btn('演示读取','demo-only','primary'))
};
function scResolveConflict(incoming){const f=scFiles.find(x=>x.id===scSelected.id);if(incoming)f.working=f.incoming;f.conflict=false;scStage(f.id);$('#dialog').close();scNotice='冲突结果已暂存（示例）；填写说明后提交。';scRefresh()}
